content.content:
1	/* Local-only interface styles. No remote fonts, images, or CDN assets. */
2	
3	/*
4	 * Warm-dark tokens reconstructed from the reference screenshot as starting
5	 * values (UX-01). They are approximate calibration targets, not exact
6	 * Superhuman values; geometry is calibrated on real displays later.
7	 */
8	:root {
9	  color-scheme: dark;
10	  font-family: var(--font-ui);
11	  /*
12	   * Type scale (DESIGN.md "Typography"): one local system sans, a fixed rem
13	   * scale, two weights. Hierarchy comes from weight (600 vs 400) and tone
14	   * (Paper White vs Ash), not from extra sizes.
15	   */
16	  --font-ui: system-ui, -apple-system, sans-serif;
17	  --font-mono: ui-monospace, monospace;
18	  /* 16px: split tabs, context title, contact name, drawer and reader headings. */
19	  --type-headline: 1rem;
20	  /* 12px: everything else in the app shell (rows, rail, panes, drawers, reader chrome). */
21	  --type-body: 0.75rem;
22	  /* 11px: split-tab counts only. */
23	  --type-count: 0.6875rem;
24	  /* Plain-text message bodies in the reader (monospace runs visually larger). */
25	  --type-mono: 0.85rem;
26	  --weight-regular: 400;
27	  --weight-strong: 600;
28	  --leading-headline: 1.25;
29	  --leading-ui: 1.35;
30	  --leading-mono: 1.45;
31	  --surface: #292826;
32	  --surface-contact: #1f1e1c;
33	  --surface-raised: #33312e;
34	  --focus-fill: #474644;
35	  --focus-accent: #bba5ed;
36	  /* DESIGN.md Paper White: 14.7:1 on Warm Charcoal, 9.4:1 on Focus Stone. */
37	  --text-primary: #ffffff;
38	  /* DESIGN.md Ash: >=4.5:1 on Focus Stone (4.99:1; the old #a8a29a was 3.73:1). */
39	  --text-secondary: #c0bcb6;
40	  /* DESIGN.md Smoke (inactive split tabs, on Warm Charcoal only: 5.4:1) and
41	     Graphite (resting glyphs). */
42	  --text-tertiary: #a09c9a;
43	  --icon-muted: #8e8a87;
44	  /* DESIGN.md split-header height: content top to the first row. */
45	  --split-header-height: 78px;
46	  --unread-marker: #ce9ece;
47	  --divider: #3b3936;
48	  /* DESIGN.md Inkwell (rail destination pill) and Rail Pebble (28px circle,
49	     active destination). */
50	  --rail-well: #141413;
51	  --rail-button: #383735;
52	  /* Pane geometry shared by the rail and the contact pane so their lines
53	     follow the list column: the split-tab line is centered 42px down (6px
54	     header pad + half of its 72px row), the first list line is the 36px row
55	     right below the 78px header. */
56	  --rail-width: 40px;
57	  --contact-width: 272px;
58	  --contact-inset: 24px;
59	  --tab-line: 42px;
60	  --first-line: calc(var(--split-header-height) + 18px);
61	  --warning: #e4c465;
62	  --danger: #f1a9a5;
63	}
64	
65	* {
66	  box-sizing: border-box;
67	}
68	
69	body {
70	  margin: 0;
71	}
72	
73	button {
74	  background: var(--surface-raised);
75	  color: var(--text-primary);
76	  border: 1px solid var(--divider);
77	  border-radius: 4px;
78	  padding: 0.15rem 0.5rem;
79	  font: inherit;
80	}
81	
82	button:focus-visible {
83	  outline: 2px solid var(--focus-accent);
84	  outline-offset: 1px;
85	}
86	
87	select {
88	  font: inherit;
89	}
90	
91	input,
92	textarea {
93	  font: inherit;
94	  background: var(--surface-raised);
95	  color: var(--text-primary);
96	  border: 1px solid var(--divider);
97	  border-radius: 4px;
98	}
99	
100	.app {
101	  display: flex;
102	  flex-direction: column;
103	  height: 100vh;
104	  background: var(--surface);
105	  color: var(--text-primary);
106	}
107	
108	/* UX-13A: disclosed browser workspaces, deliberately not a native tab strip. */
109	.fixture-workspaces {
110	  height: 100vh;
111	  display: flex;
112	  flex-direction: column;
113	  background: var(--surface);
114	  color: var(--text-primary);
115	}
116	.workspace-header {
117	  padding: 0.4rem 0.75rem;
118	  border-bottom: 1px solid var(--divider);
119	  font-size: var(--type-body);
120	}
121	.workspace-header p { margin: 0 0 0.35rem; }
122	.workspace-header nav { display: flex; flex-wrap: wrap; gap: 0.4rem; }
123	.workspace-header button[aria-current] { background: var(--focus-fill); }
124	.workspace-panel { flex: 1; min-height: 0; }
125	.workspace-panel > .app { height: 100%; }
126	
127	/* Shared: in the accessibility tree, not on screen. */
128	.visually-hidden {
129	  position: absolute;
130	  width: 1px;
131	  height: 1px;
132	  overflow: hidden;
133	  clip-path: inset(50%);
134	  white-space: nowrap;
135	}
136	
137	/*
138	 * Heading defaults inside the shell (zero specificity, so component classes
139	 * win): h2 is a Headline, h3/h4 are Title labels. No default 700 weight.
140	 */
141	:where(.app-main) h2 {
142	  font-size: var(--type-headline);
143	  font-weight: var(--weight-regular);
144	  line-height: var(--leading-headline);
145	}
146	
147	:where(.app-main) :is(h3, h4) {
148	  font-size: var(--type-body);
149	  font-weight: var(--weight-strong);
150	  line-height: var(--leading-ui);
151	}
152	
153	:where(.app-main) :is(strong, b) {
154	  font-weight: var(--weight-strong);
155	}
156	
157	/*
158	 * Split header (DESIGN.md "Split Tabs"): one borderless 78px strip in the list
159	 * column. Hamburger centered 23px into the pane, tabs on the 50px content
160	 * inset and vertically centered ~42px down, right glyphs on the 32px action
161	 * pitch with the last glyph centered 32px from the pane edge. Extra rows
162	 * (split editor, split error) wrap below the tab line.
163	 */
164	.app-header {
165	  display: grid;
166	  grid-template-columns: 50px minmax(0, 1fr) minmax(0, auto);
167	  grid-template-rows: minmax(calc(var(--split-header-height) - 6px), auto);
168	  align-items: center;
169	  padding: 6px 16px 0 0;
170	  background: var(--surface);
171	}
172	
173	.app-header > .header-row {
174	  grid-column: 1 / -1;
175	  padding-left: 50px;
176	}
177	
178	.header-alert {
179	  margin: 0 0 0.5rem;
180	  font-size: var(--type-body);
181	  color: var(--danger);
182	}
183	
184	/* Ghost glyph button: Graphite at rest, Paper White on hover/focus. */
185	.header-glyph {
186	  flex: 0 0 auto;
187	  display: inline-grid;
188	  place-items: center;
189	  width: 32px;
190	  height: 32px;
191	  padding: 0;
192	  background: transparent;
193	  border: 0;
194	  border-radius: 4px;
195	  color: var(--icon-muted);
196	  cursor: pointer;
197	}
198	
199	.header-glyph:hover:not(:disabled),
200	.header-glyph:focus-visible,
201	.header-glyph[aria-pressed='true'] {
202	  color: var(--text-primary);
203	}
204	
205	.header-glyph:disabled {
206	  opacity: 0.45;
207	  cursor: default;
208	}
209	
210	.header-glyph-icon {
211	  width: 1rem;
212	  height: 1rem;
213	}
214	
215	.header-menu {
216	  justify-self: start;
217	  margin-left: 7px;
218	}
219	
220	.header-tabs {
221	  display: flex;
222	  align-items: baseline;
223	  gap: 18px;
224	  min-width: 0;
225	  overflow: hidden;
226	  /* Room for the focus ring of the first tab inside the clipped line. */
227	  padding: 4px 4px 4px 0;
228	  margin: -4px 0;
229	}
230	
231	.app-title,
232	.split-tab {
233	  font-size: var(--type-headline);
234	  font-weight: var(--weight-regular);
235	  line-height: var(--leading-headline);
236	}
237	
238	.app-title {
239	  margin: 0;
240	  min-width: 0;
241	  flex: 0 1 auto;
242	  overflow: hidden;
243	  text-overflow: ellipsis;
244	  white-space: nowrap;
245	  color: var(--text-primary);
246	}
247	
248	.app-title-account {
249	  font-size: var(--type-body);
250	  color: var(--text-secondary);
251	}
252	
253	.split-nav {
254	  display: flex;
255	  align-items: baseline;
256	  gap: 18px;
257	  min-width: 0;
258	}
259	
260	.split-tab {
261	  display: inline-flex;
262	  align-items: baseline;
263	  gap: 4px;
264	  min-width: 0;
265	  padding: 0;
266	  background: transparent;
267	  border: 0;
268	  border-radius: 2px;
269	  color: var(--text-tertiary);
270	  white-space: nowrap;
271	  cursor: pointer;
272	}
273	
274	.split-tab:hover,
275	.split-tab[aria-current='page'] {
276	  color: var(--text-primary);
277	}
278	
279	.split-tab:focus-visible {
280	  outline-offset: 2px;
281	}
282	
283	.split-label {
284	  min-width: 0;
285	  overflow: hidden;
286	  text-overflow: ellipsis;
287	}
288	
289	.split-count {
290	  flex: 0 0 auto;
291	  font-size: var(--type-count);
292	  line-height: 1;
293	  color: var(--text-secondary);
294	  font-variant-numeric: tabular-nums;
295	}
296	
297	/* Active list filter, in words beside the tabs. */
298	.header-filter {
299	  flex: 0 0 auto;
300	  font-size: var(--type-body);
301	  color: var(--text-secondary);
302	  white-space: nowrap;
303	}
304	
305	.header-trail {
306	  display: flex;
307	  align-items: center;
308	  justify-content: flex-end;
309	  min-width: 0;
310	}
311	
312	/* Compact one-line notes; they give up width before the glyphs do. */
313	.header-note {
314	  flex: 0 1 auto;
315	  min-width: 0;
316	  margin: 0 12px 0 0;
317	  overflow: hidden;
318	  text-overflow: ellipsis;
319	  white-space: nowrap;
320	  font-size: var(--type-body);
321	  color: var(--text-secondary);
322	}
323	
324	.preview-tag {
325	  color: var(--warning);
326	}
327	
328	.header-link {
329	  padding: 0 2px;
330	  background: transparent;
331	  border: 0;
332	  color: var(--text-primary);
333	  font-size: inherit;
334	  cursor: pointer;
335	}
336	
337	.header-link:hover {
338	  text-decoration: underline;
339	}
340	
341	.command-error {
342	  margin: 0;
343	  padding: 0.4rem 1rem 0.4rem 50px;
344	  color: var(--danger);
345	  font-size: var(--type-body);
346	  font-weight: var(--weight-strong);
347	}
348	
349	.draft-close-recovery {
350	  border-bottom: 1px solid var(--divider);
351	  padding: 0.4rem 0.75rem;
352	  color: var(--warning);
353	  display: flex;
354	  gap: 0.75rem;
355	  align-items: center;
356	  flex-wrap: wrap;
357	}
358	
359	.draft-close-recovery p {
360	  margin: 0;
361	}
362	
363	/*
364	 * Rail + one central list-or-reader surface + contact context. The contact
365	 * column exists only at >=1000 CSS px; strictly below it, the rail exposes a
366	 * keyboard-operable Contact disclosure instead.
367	 */
368	.app-main {
369	  /* Shell body type: everything not on another step of the scale is 12px. */
370	  font-size: var(--type-body);
371	  line-height: var(--leading-ui);
372	  display: grid;
373	  grid-template-columns: auto minmax(0, 1fr);
374	  /* Header, in-flow notices, then the list-or-reader surface; the rail and
375	     contact pane span all three so the header lives in the list column. */
376	  grid-template-rows: auto auto minmax(0, 1fr);
377	  flex: 1;
378	  min-height: 0;
379	  position: relative;
380	}
381	
382	.app-main > .rail {
383	  grid-column: 1;
384	  grid-row: 1 / -1;
385	}
386	
387	.app-main > .app-header,
388	.app-main > .list-notices {
389	  grid-column: 2;
390	}
391	
392	.app-main > .app-header { grid-row: 1; }
393	.app-main > .list-notices { grid-row: 2; min-width: 0; }
394	
395	.app-main > .central,
396	.app-main > .account-gate {
397	  grid-column: 2;
398	  grid-row: 3;
399	}
400	
401	.app-main > .contact-column {
402	  grid-column: 3;
403	  grid-row: 1 / -1;
404	}
405	
406	@media (min-width: 1000px) {
407	  .app-main {
408	    grid-template-columns: auto minmax(0, 1fr) var(--contact-width);
409	  }
410	}
411	
412	.rail {
413	  /* 40px icon rail (DESIGN.md "Rail"). Fixed px so larger root fonts widen
414	     the list, never the rail. Above the row-actions popover (6), below the
415	     utility drawers (30), so the keyboard tooltip clears the list. */
416	  position: relative;
417	  z-index: 20;
418	  display: flex;
419	  flex-direction: column;
420	  align-items: center;
421	  width: var(--rail-width);
422	  /* The home circle is centered on the split-tab line. */
423	  padding: calc(var(--tab-line) - 14px) 0 16px;
424	  border-right: 1px solid var(--divider);
425	  background: var(--surface);
426	}
427	
428	/* Ghost glyph button: Graphite at rest, Paper White on hover, focus and when
429	   current. The circle behind an active glyph is drawn by ::before so the
430	   28px hit area keeps the 28px pitch inside the pill. */
431	.rail-item {
432	  position: relative;
433	  flex: 0 0 auto;
434	  display: grid;
435	  place-items: center;
436	  width: 28px;
437	  height: 28px;
438	  padding: 0;
439	  background: transparent;
440	  border: 0;
441	  border-radius: 9999px;
442	  color: var(--icon-muted);
443	  cursor: pointer;
444	}
445	
446	.rail-item::before {
447	  content: '';
448	  position: absolute;
449	  inset: 2px;
450	  border-radius: 9999px;
451	  background: transparent;
452	}
453	
454	.rail-item > svg {
455	  position: relative;
456	}
457	
458	.rail-item:hover,
459	.rail-item:focus-visible,
460	.rail-item[aria-current='page'],
461	.rail-item[aria-expanded='true'] {
462	  color: var(--text-primary);
463	}
464	
465	.rail-item[aria-current='page']::before,
466	.rail-item[aria-expanded='true']::before {
467	  background: var(--rail-button);
468	}
469	
470	/* Inbox: the Rail Pebble home circle on the split-tab line. */
471	.rail-home::before {
472	  inset: 0;
473	  background: var(--rail-button);
474	}
475	
476	/* Inkwell pill: starts at the header's bottom edge so its first glyph is
477	   centered on the first list line (78px + 18px). */
478	.rail-well {
479	  display: flex;
480	  flex-direction: column;
481	  align-items: center;
482	  width: 30px;
483	  margin-top: calc(var(--first-line) - var(--tab-line) - 14px - 14px - 1px);
484	  padding: 1px 0;
485	  border-radius: 9999px;
486	  background: var(--rail-well);
487	}
488	
489	.rail-utilities {
490	  display: flex;
491	  flex-direction: column;
492	  align-items: center;
493	  gap: 4px;
494	}
495	
496	/*
497	 * The label is the button's accessible name (textContent) and, on keyboard
498	 * focus, a tooltip beside the rail; pointer hover uses the native title, as
499	 * the header glyphs do. Visually hidden otherwise.
500	 */
501	.rail-label {
502	  position: absolute;
503	  width: 1px;
504	  height: 1px;
505	  overflow: hidden;
506	  clip-path: inset(50%);
507	  white-space: nowrap;
508	}
509	
510	.rail-item:focus-visible > .rail-label {
511	  left: calc(100% + 10px);
512	  top: 50%;
513	  width: auto;
514	  height: auto;
515	  overflow: visible;
516	  clip-path: none;
517	  transform: translateY(-50%);
518	  padding: 2px 8px;
519	  border-radius: 4px;
520	  background: var(--surface-raised);
521	  color: var(--text-primary);
522	  font-size: var(--type-body);
523	  line-height: var(--leading-ui);
524	  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
525	  pointer-events: none;
526	}
527	
528	/* Unresolved operations on Activity: Amber Notice count, named in words by
529	   the button's description and title. */
530	.rail-badge {
531	  position: absolute;
532	  top: -1px;
533	  right: -3px;
534	  min-width: 14px;
535	  height: 14px;
536	  padding: 0 3px;
537	  border-radius: 9999px;
538	  background: var(--warning);
539	  color: var(--surface-contact);
540	  font-size: var(--type-count);
541	  font-weight: var(--weight-strong);
542	  line-height: 14px;
543	  text-align: center;
544	  font-variant-numeric: tabular-nums;
545	  pointer-events: none;
546	}
547	
548	.rail-spacer {
549	  flex: 1;
550	}
551	
552	.central {
553	  min-height: 0;
554	  min-width: 0;
555	  display: flex;
556	  flex-direction: column;
557	  overflow: hidden;
558	}
559	
560	/*
561	 * Contact context column (DESIGN.md "Contact Pane"): 272px on Deep Umber with
562	 * a 24px inset. The name is centered on the split-tab line and the email on
563	 * the first list line; recent cached mail runs at a 24px pitch. These pinned
564	 * lines apply to the wide column only; the narrow disclosure stacks them.
565	 */
566	.contact-column {
567	  border-left: 1px solid var(--divider);
568	  background: var(--surface-contact);
569	  overflow-y: auto;
570	  padding: 0 var(--contact-inset) var(--contact-inset);
571	  min-height: 0;
572	  min-width: 0;
573	}
574	
575	.contact-identity {
576	  margin: 0;
577	}
578	
579	/* One line per identity field: the value, then its copy glyph. The glyph
580	   sits in the line's trailing slot, so a hidden glyph never adds a line. */
581	.contact-line {
582	  display: flex;
583	  align-items: center;
584	  gap: 4px;
585	  margin: 0;
586	  min-width: 0;
587	}
588	
589	.contact-line > :first-child {
590	  min-width: 0;
591	  overflow-wrap: anywhere;
592	}
593	
594	/* Name: centered on the tab line within a header-height block; a long name
595	   wraps around that center before it pushes the email down. */
596	.contact-column .contact-line-name,
597	.contact-column .contact-unknown {
598	  min-height: var(--split-header-height);
599	  padding-top: 6px;
600	}
601	
602	.contact-column .contact-unknown {
603	  display: flex;
604	  align-items: center;
605	}
606	
607	/* Email: the 36px line after the header block, i.e. the first list line. */
608	.contact-column .contact-line-mailbox {
609	  min-height: 36px;
610	}
611	
612	/* Headline: the contact name is the pane's one large line. */
613	.contact-name {
614	  font-size: var(--type-headline);
615	  font-weight: var(--weight-regular);
616	  line-height: var(--leading-headline);
617	  color: var(--text-primary);
618	}
619	
620	.contact-search {
621	  background: none;
622	  border: 0;
623	  padding: 0;
624	  text-align: left;
625	  overflow-wrap: anywhere;
626	  cursor: pointer;
627	}
628	.contact-search:hover { text-decoration: underline; }
629	
630	/* Title: the email is Paper White semibold (DESIGN.md contact-pane). */
631	.contact-mailbox {
632	  color: var(--text-primary);
633	  font-size: var(--type-body);
634	  font-weight: var(--weight-strong);
635	}
636	
637	.contact-unknown {
638	  color: var(--text-secondary);
639	  font-size: var(--type-body);
640	  margin: 0;
641	}
642	
643	/* Mail section: a Title label with a Graphite glyph, then plain Ash text
644	   rows (no chips) at a 24px pitch, one line each with an ellipsis. */
645	.contact-recent {
646	  margin-top: 0;
647	}
648	
649	.contact-recent h3 {
650	  display: flex;
651	  align-items: center;
652	  gap: 8px;
653	  min-height: 30px;
654	  margin: 0;
655	  font-size: var(--type-body);
656	  font-weight: var(--weight-strong);
657	  color: var(--text-primary);
658	}
659	
660	.contact-recent h3 > svg {
661	  flex: 0 0 auto;
662	  color: var(--icon-muted);
663	}
664	
665	.contact-recent ul {
666	  list-style: none;
667	  margin: 0;
668	  padding: 0;
669	}
670	
671	.contact-recent li {
672	  margin: 0;
673	}
674	
675	.contact-recent button {
676	  display: block;
677	  width: 100%;
678	  height: 24px;
679	  padding: 0;
680	  overflow: hidden;
681	  background: transparent;
682	  border: 0;
683	  border-radius: 2px;
684	  color: var(--text-secondary);
685	  text-align: left;
686	  text-overflow: ellipsis;
687	  white-space: nowrap;
688	  cursor: pointer;
689	}
690	
691	.contact-recent button:hover,
692	.contact-recent button:focus-visible {
693	  color: var(--text-primary);
694	}
695	
696	/* Inside the narrow disclosure: compact stacking under the drawer header. */
697	.contact-disclosure-panel .contact-line-name { min-height: 28px; }
698	.contact-disclosure-panel .contact-line-mailbox { min-height: 24px; }
699	.contact-disclosure-panel .contact-recent { margin-top: 12px; }
700	
701	.mail-search { padding: 1rem; border-bottom: 1px solid var(--divider); }
702	.mail-search-entry { display: flex; gap: 0.5rem; flex-wrap: wrap; margin: 0.5rem 0; }
703	.mail-search-entry input { flex: 1 1 16rem; min-width: 0; }
704	.mail-search p { max-width: 75ch; color: var(--text-secondary); }
705	/*
706	 * Utility disclosures overlay the central surface; they are never columns.
