// CDP driver for the polish pass: node polish.mjs <outDir> <prefix> <scenario...>
import { spawn } from 'node:child_process';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const CHROME = '/Users/sofianebebert/Library/Caches/ms-playwright/chromium-1228/chrome-mac-arm64/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing';
const [outDir, prefix, ...scenarios] = process.argv.slice(2);
const profile = mkdtempSync(join(process.env.TMPDIR ?? tmpdir(), 'cdp-'));
const port = 9334;
const chrome = spawn(CHROME, ['--headless=new', `--remote-debugging-port=${port}`, `--user-data-dir=${profile}`, '--no-first-run', '--hide-scrollbars', 'about:blank'], { stdio: 'ignore' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let targets;
for (let i = 0; i < 50; i++) { try { targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); break; } catch { await sleep(200); } }
const page = targets.find((t) => t.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener('open', r));
let id = 0; const pending = new Map();
const consoleErrors = [];
ws.addEventListener('message', (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } if (m.method === 'Runtime.exceptionThrown') consoleErrors.push(m.params.exceptionDetails.text); if (m.method === 'Runtime.consoleAPICalled' && ['error', 'warning'].includes(m.params.type)) consoleErrors.push(m.params.args.map((a) => a.value ?? a.description).join(' ')); });
const cmd = (method, params = {}) => new Promise((res) => { const i = ++id; pending.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
const js = async (expr) => { const r = await cmd('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }); if (r.result.exceptionDetails) throw new Error(JSON.stringify(r.result.exceptionDetails)); return r.result.result.value; };
await cmd('Runtime.enable');
async function size(w, h) { await cmd('Emulation.setDeviceMetricsOverride', { width: w, height: h, deviceScaleFactor: 2, mobile: false }); }
async function load(w, h, gmail) {
  await size(w, h); await cmd('Page.navigate', { url: 'http://localhost:5199/' }); await sleep(1500);
  if (gmail) {
    await js(`(async () => {
      const vueUrl = performance.getEntriesByType('resource').map((x) => x.name).find((n) => n.includes('/node_modules/.vite/deps/vue.js'));
      const { createApp } = await import(vueUrl);
      const { default: App } = await import('/src/App.vue');
      const { createBrowserFakeMailClient } = await import('/src/lib/ipc/browser-fake.ts');
      const root = document.querySelector('#app'); root.__vue_app__?.unmount();
      const fake = createBrowserFakeMailClient();
      window.__fake = fake;
      fake.controls.setAccount({ mode: 'gmail', connection: 'connected', emailAddress: 'review@example.test', mutationAccess: 'enabled', coverageLimit: 100 });
      createApp(App, { client: fake, mode: 'browser-preview' }).mount(root);
      await new Promise(r => setTimeout(r, 600));
      fake.controls.markReadUnknown('conv-03');
      await new Promise(r => setTimeout(r, 300));
    })()`);
  } else {
    await js(`(() => { const st = document.createElement('style'); st.textContent = '.workspace-header{display:none}'; document.head.append(st); window.__fake = document.querySelector('#app').__vue_app__._instance.props.sessions[0].client; })()`);
  }
  await sleep(200);
}
async function key(k, code, vk, mods = 0) { await cmd('Input.dispatchKeyEvent', { type: 'keyDown', key: k, code, text: mods ? undefined : k, windowsVirtualKeyCode: vk, modifiers: mods }); await cmd('Input.dispatchKeyEvent', { type: 'keyUp', key: k, code, windowsVirtualKeyCode: vk, modifiers: mods }); await sleep(250); }
const focusRow = (conv) => js(`document.querySelector('[data-test="conversation-row-${conv}"]').focus()`);
async function shot(name) { const r = await cmd('Page.captureScreenshot', { format: 'png' }); writeFileSync(join(outDir, name), Buffer.from(r.result.data, 'base64')); }
const firstRow = () => js(`(() => { const el = document.querySelector('.inbox-row'); if (!el) return null; const b = el.getBoundingClientRect(); return { top: +b.top.toFixed(1), cy: +(b.top + b.height / 2).toFixed(1), id: el.dataset.test }; })()`);
const focusedRowY = () => js(`(() => { const el = document.querySelector('.inbox-row.focused'); if (!el) return null; const b = el.getBoundingClientRect(); return { top: +b.top.toFixed(1), id: el.dataset.test }; })()`);
const box = (sel) => js(`(() => { const el = document.querySelector(${JSON.stringify(sel)}); if (!el) return null; const b = el.getBoundingClientRect(); return { l: +b.left.toFixed(1), t: +b.top.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1) }; })()`);
const textOf = (sel) => js(`document.querySelector(${JSON.stringify(sel)})?.textContent?.replace(/\\s+/g, ' ').trim() ?? null`);
const metrics = () => js(`(() => {
  const r = (s) => { const el = document.querySelector(s); if (!el) return null; const b = el.getBoundingClientRect(); return { l: +b.left.toFixed(1), t: +b.top.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1), cy: +(b.top + b.height / 2).toFixed(1) }; };
  const rows = [...document.querySelectorAll('.inbox-row')].slice(0, 4).map((el) => ({ id: el.dataset.test, unread: !!el.querySelector('[data-test="row-unread"]'), unknown: !!el.querySelector('[data-test="row-read-unknown"]'), w: getComputedStyle(el.querySelector('.row-sender')).fontWeight }));
  return { tab: r('.split-tab[aria-current] .split-label') ?? r('.app-title'), firstRow: r('.inbox-row'), firstGroup: r('.row-group'), groups: [...document.querySelectorAll('.row-group')].map((g) => g.textContent.trim()).slice(0, 4), mailbox: r('[data-test="contact-mailbox"]'), firstWell: r('.rail-well .rail-item'), rows, notices: r('.list-notices') };
})()`);

const results = {};
for (const s of scenarios) {
  const gmail = !s.endsWith('-fixture');
  const base = s.replace(/-fixture$/, '');
  if (base === 'w1030') { await load(1030, 800, gmail); await focusRow('conv-01'); await sleep(200); results[s] = await metrics(); await shot(`${prefix}-1030${gmail ? '' : '-fixture'}.png`); }
  if (base === 'w1280') { await load(1280, 800, gmail); await focusRow('conv-01'); await sleep(200); results[s] = await metrics(); await shot(`${prefix}-1280${gmail ? '' : '-fixture'}.png`); }
  if (base === 'shift') {
    // Layout shift: first row y and focused row y before/after x, e, z.
    await load(1280, 800, gmail);
    await focusRow('conv-02'); await sleep(150);
    const seq = { start: { first: await firstRow(), focused: await focusedRowY() } };
    await key('x', 'KeyX', 88);
    seq.x1 = { first: await firstRow(), focused: await focusedRowY(), bar: await box('[data-test="selection-bar"]') };
    await key('j', 'KeyJ', 74);
    await key('x', 'KeyX', 88);
    seq.x2 = { first: await firstRow(), focused: await focusedRowY(), scope: await textOf('[data-test="selection-scope"]') };
    await shot(`${prefix}-selection.png`);
    // Clear the selection with Escape, then archive the focused row.
    await key('Escape', 'Escape', 27);
    seq.cleared = { first: await firstRow(), focused: await focusedRowY() };
    await key('e', 'KeyE', 69); await sleep(400);
    seq.e = { first: await firstRow(), focused: await focusedRowY(), notice: await box('[data-test="action-notice"]'), text: await textOf('[data-test="action-notice"]') };
    await shot(`${prefix}-notice.png`);
    await key('z', 'KeyZ', 90); await sleep(500);
    seq.z = { first: await firstRow(), focused: await focusedRowY(), text: await textOf('[data-test="action-notice"]') };
    results[s] = seq;
  }
  if (base === 'palette') {
    await load(1280, 800, gmail); await focusRow('conv-01'); await sleep(150);
    await js(`document.querySelector('[data-test="palette-trigger"]').click()`); await sleep(400);
    await key('ArrowDown', 'ArrowDown', 40);
    results[s] = await js(`(() => { const o = document.querySelector('.action-overlay'); const b = o.getBoundingClientRect(); const cs = (el, p) => el ? getComputedStyle(el)[p] : null; const li = o.querySelector('li.highlighted'); return { w: b.width, t: b.top, radius: cs(o, 'borderRadius'), bg: cs(o, 'backgroundColor'), input: cs(o.querySelector('input'), 'fontSize'), li: cs(li, 'fontSize'), liPad: cs(li, 'padding'), liH: li?.getBoundingClientRect().height, kbd: cs(o.querySelector('kbd'), 'color') }; })()`);
    await shot(`${prefix}-palette.png`);
  }
  if (base === 'drawer') {
    await load(1280, 800, gmail);
    await js(`document.querySelector('[data-test="rail-account"]').click()`); await sleep(400);
    await shot(`${prefix}-drawer-account.png`);
    await js(`document.querySelector('[data-test="rail-activity"]').click()`); await sleep(400);
    await shot(`${prefix}-drawer-activity.png`);
  }
  if (base === 'done') {
    await load(1280, 800, gmail);
    await js(`document.querySelector('[data-test="rail-done"]').click()`); await sleep(500);
    results[s] = { coverage: await textOf('[data-test="done-coverage"]'), metrics: await metrics() };
    await shot(`${prefix}-done.png`);
  }
}
results.consoleErrors = consoleErrors;
console.log(JSON.stringify(results, null, 1));
ws.close(); chrome.kill(); await sleep(300); rmSync(profile, { recursive: true, force: true });

